const body = $input.first().json.body ?? {};
const errors = [];
const contractVersion = 'calendar.generate.v1';
const allowedModels = new Set(['openai/gpt-oss-20b', 'openai/gpt-oss-120b']);
const isText = (value, max) => typeof value === 'string' && value.trim().length > 0 && value.length <= max;

if (body.contract_version !== contractVersion) errors.push('contract_version must be calendar.generate.v1');
if (!isText(body.request_id, 128)) errors.push('request_id is required and must be 128 characters or fewer');
if (body.campaign_id != null && !isText(body.campaign_id, 128)) errors.push('campaign_id must be a non-empty string of 128 characters or fewer');
if (!allowedModels.has(body.model)) errors.push('model must be openai/gpt-oss-20b or openai/gpt-oss-120b');
if (!Number.isInteger(body.expected_posts) || body.expected_posts < 1 || body.expected_posts > 30) errors.push('expected_posts must be an integer from 1 to 30');
if (!isText(body.system_prompt, 20000)) errors.push('system_prompt is required and must be 20,000 characters or fewer');
if (!isText(body.user_prompt, 40000)) errors.push('user_prompt is required and must be 40,000 characters or fewer');

if (errors.length) {
  return [{ json: { valid: false, http_status: 400, response: {
    contract_version: contractVersion,
    ok: false,
    request_id: typeof body.request_id === 'string' ? body.request_id : null,
    campaign_id: typeof body.campaign_id === 'string' ? body.campaign_id : null,
    error: { code: 'INVALID_REQUEST', message: errors.join('; '), retryable: false }
  }}}];
}

return [{ json: {
  valid: true,
  request_id: body.request_id,
  campaign_id: body.campaign_id ?? null,
  model: body.model,
  expected_posts: body.expected_posts,
  groq_payload: {
    model: body.model,
    messages: [
      { role: 'system', content: body.system_prompt },
      { role: 'user', content: body.user_prompt }
    ],
    temperature: 0.3,
    max_completion_tokens: 8192,
    reasoning_effort: 'low',
    include_reasoning: false
  }
}}];

const upstream = $input.first().json;
const request = $('Validate Contract and Build Groq Request').first().json;
const status = Number(upstream.statusCode ?? 0);
const body = upstream.body && typeof upstream.body === 'object' ? upstream.body : {};
const contractVersion = 'calendar.generate.v1';

const failure = (httpStatus, code, message, retryable) => [{ json: {
  http_status: httpStatus,
  response: {
    contract_version: contractVersion,
    ok: false,
    request_id: request.request_id,
    campaign_id: request.campaign_id,
    error: { code, message, retryable }
  }
}}];

if (status < 200 || status >= 300) {
  if (status === 429) return failure(429, 'GROQ_RATE_LIMIT', 'Groq rate limit reached. Try again later.', true);
  if (status === 401 || status === 403) return failure(502, 'GROQ_AUTH_ERROR', 'The n8n Groq credential is invalid or unauthorized.', false);
  return failure(502, 'GROQ_REQUEST_FAILED', 'Groq request failed.', status === 0 || status >= 500);
}

const choices = Array.isArray(body.choices) ? body.choices : [];
const choice = choices[0] && typeof choices[0] === 'object' ? choices[0] : {};
const message = choice.message && typeof choice.message === 'object' ? choice.message : {};
const calendarMarkdown = typeof message.content === 'string' ? message.content.trim() : '';
const finishReason = typeof choice.finish_reason === 'string' ? choice.finish_reason : 'unknown';

if (!calendarMarkdown) {
  const code = finishReason === 'length' ? 'GROQ_OUTPUT_LIMIT' : 'GROQ_EMPTY_RESPONSE';
  const text = finishReason === 'length' ? 'Groq reached its output limit before returning the calendar.' : 'Groq returned an empty calendar.';
  return failure(502, code, text, true);
}

const usage = body.usage && typeof body.usage === 'object' ? {
  prompt_tokens: Number(body.usage.prompt_tokens ?? 0),
  completion_tokens: Number(body.usage.completion_tokens ?? 0),
  total_tokens: Number(body.usage.total_tokens ?? 0)
} : null;

return [{ json: {
  http_status: 200,
  response: {
    contract_version: contractVersion,
    ok: true,
    request_id: request.request_id,
    campaign_id: request.campaign_id,
    provider: 'n8n',
    upstream_provider: 'groq',
    model: request.model,
    expected_posts: request.expected_posts,
    calendar_markdown: calendarMarkdown,
    finish_reason: finishReason,
    usage
  }
}}];
